CREATE OR REPLACE PACKAGE BODY billing_api AS
  procedure pay(p_bill_id in number, p_amount in number) is
  begin
    insert into bill_payments (bill_id, amount)
    values (p_bill_id, p_amount);

    update bills
    set status = CASE 
                   WHEN (select sum(amount) from bill_payments where bill_id = p_bill_id) >= total_amount 
                   THEN 'PAID' 
                   ELSE 'PARTIAL' 
                 END
    where bill_id = p_bill_id;
  end pay;
END billing_api;
/
